<script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api,http}from'../api';const list=ref([]),dialog=ref(false),saving=ref(false),promoRange=ref([]);const empty=()=>({id:null,name:'',category:'大池',cover:'',benefits:[{benefitId:'',item:'',type:'times',total:1,step:1}],price:0,salePrice:0,activityPrice:null,activityStartAt:null,activityEndAt:null,validDays:30,rules:'限本人使用，不可转赠',status:0,sort:0});let form=reactive(empty());const load=async()=>list.value=await api.products();onMounted(load);function edit(row){Object.assign(form,empty(),JSON.parse(JSON.stringify(row)));promoRange.value=form.activityStartAt?[form.activityStartAt,form.activityEndAt]:[];dialog.value=true}function addBenefit(){form.benefits.push({benefitId:crypto.randomUUID().slice(0,8),item:'',type:'times',total:1,step:1})}async function save(){form.activityStartAt=promoRange.value?.[0]||null;form.activityEndAt=promoRange.value?.[1]||null;saving.value=true;try{await api.saveProduct(form.id,form);ElMessage.success('商品已保存');dialog.value=false;await load()}finally{saving.value=false}}async function toggle(r){await api.productStatus(r.id,r.status?0:1);await load()}async function remove(r){await ElMessageBox.confirm(`确认删除「${r.name}」？历史订单不受影响。`,'删除商品',{type:'warning'});await api.deleteProduct(r.id);await load()}async function upload(e){const fd=new FormData();fd.append('file',e.target.files[0]);const r=await http.post('/admin/upload',fd);form.cover=r.url}</script>
<template><div class="page-head"><div><h2>卡商品</h2><p>配置售价、活动价、有效期与可核销权益</p></div><el-button type="primary" @click="edit(empty())">新增卡商品</el-button></div><div class="panel"><el-table :data="list"><el-table-column label="商品" min-width="220"><template #default="{row}"><div style="display:flex;gap:12px;align-items:center"><img class="thumb" :src="row.cover||'data:image/gif;base64,R0lGODlhAQABAAAAACw='"/><div><b>{{row.name}}</b><div class="muted">{{row.category}} · {{row.validDays}} 天</div></div></div></template></el-table-column><el-table-column label="售价" width="150"><template #default="{row}"><span class="price">¥{{row.currentPrice}}</span><div class="muted">原价 ¥{{row.price}}</div></template></el-table-column><el-table-column prop="benefits" label="权益"><template #default="{row}"><el-tag v-for="b in row.benefits" :key="b.benefitId" style="margin-right:5px">{{b.item}} {{b.type==='unlimited'?'不限次':b.total}}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-switch :model-value="row.status===1" @change="toggle(row)"/></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="form.id?'编辑卡商品':'新增卡商品'" width="760px"><el-form label-position="top"><div style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px"><el-form-item label="商品名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="分类"><el-select v-model="form.category" style="width:100%"><el-option v-for="x in ['大池','包间','综合','其他']" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="原价"><el-input-number v-model="form.price" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="售价"><el-input-number v-model="form.salePrice" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="活动价"><el-input-number v-model="form.activityPrice" :min="0.01" :precision="2" style="width:100%" clearable/></el-form-item><el-form-item label="活动价时间"><el-date-picker v-model="promoRange" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="有效天数"><el-input-number v-model="form.validDays" :min="1" style="width:100%"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" style="width:100%"/></el-form-item></div><el-form-item label="封面图"><div style="display:flex;gap:10px;width:100%"><el-input v-model="form.cover" placeholder="图片 URL"/><input type="file" accept="image/png,image/jpeg,image/webp" @change="upload"/></div></el-form-item><el-form-item label="权益明细"><div style="width:100%"><div v-for="(b,i) in form.benefits" :key="i" style="display:grid;grid-template-columns:1fr 1fr 120px 100px 40px;gap:8px;margin-bottom:8px"><el-input v-model="b.benefitId" placeholder="稳定标识"/><el-input v-model="b.item" placeholder="权益名称"/><el-select v-model="b.type"><el-option label="次数" value="times"/><el-option label="小时" value="hours"/><el-option label="不限次" value="unlimited"/></el-select><el-input-number v-if="b.type!=='unlimited'" v-model="b.total" :min="0.5"/><span v-else></span><el-button text type="danger" @click="form.benefits.splice(i,1)">×</el-button></div><el-button text type="primary" @click="addBenefit">＋ 添加权益</el-button></div></el-form-item><el-form-item label="使用规则"><el-input v-model="form.rules" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></template>
